action_phrase(count_then_name_the_wrong_terminus, sequence([count_up_to_target, misname_result, record_loss]),
              gloss("Count forward to the target, then name the place reached instead of the distance travelled, or the reverse.")).
action_phrase(elaborate_then_deploy, sequence([elaborate_practice_algorithmically, deploy_vocabulary_from_practice]),
              gloss("Elaborate the practice from another by algorithm, then deploy the vocabulary that practice suffices for.")).
