action_phrase(order_and_release, sequence([compare_magnitudes, emit_result]),
              gloss("Decide the order and release it. The closing the comparison automata share.")).
action_phrase(partition_then_iterate, sequence([unitize_referent, partition_into_equal_parts, iterate_unit]),
              gloss("Constitute the whole, cut it into equal parts, then repeat one part. The fraction-scheme core in the Steffe/Olive/Hackenberg line.")).
